export const VIEW_ORIGIN_RE = new RegExp("^http://v-[0-9a-f]{16}\\.localhost:([1-9][0-9]{0,4})$", 'u');

/** The longest the hub can take to answer a view/call (view_rpc::VIEW_CALL_MAX_MS, derived from its card's one deadline, review d3): a client holds one this long, never less. */
